/* Classroom UI: all game mutations are authenticated commands to the server. */
(()=>{
'use strict';
const $=id=>document.getElementById(id),cfg=window.CLASSROOM_CONFIG||{},goods=['money','food','wood','metal'],D=RegimentDevelopment;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles={economy:'Economy',military:'Military',research:'R&D'},phaseNames=['Start & plan','Movement','Respond','Results & final actions','Year-end summary'];
const id=()=>crypto.randomUUID(),opts=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('');
const amount=x=>goods.filter(g=>x?.[g]).map(g=>`${x[g]} ${g}`).join(' · ')||'None';
const amounts=x=>`<div class="amounts">${goods.map(g=>`<div class="amount"><strong>${x?.[g]??0}</strong><span>${g}</span></div>`).join('')}</div>`;
const num=(f,name)=>Number(new FormData(f).get(name)),string=(f,name)=>String(new FormData(f).get(name)||'');
const studentPage=document.body.dataset.student==='true',demo=new URL(location.href).searchParams.has('preview'),authKey=studentPage?'cc-student-auth':'cc-classroom-auth';
let demoData=null,demoRole='economy',demoPhase='orders';
let auth=demo?null:JSON.parse(sessionStorage.getItem(authKey)||'null'),classId=new URL(location.href).searchParams.get('class')||'',v=null,cells=[],dirty=false,busy=false,polling=false,online=false,latest=null,selected=null,teacherCountry=0,teacherRole='economy',forceNext=false;
const outbox=ClassroomOutbox.create(sessionStorage);
const context=()=>({classId,actor:v.assignment.id,country:v.assignment.country,role:v.assignment.role});
function notice(text){$('notice').textContent=text;}
function remember(){if(auth)sessionStorage.setItem(authKey,JSON.stringify(auth));else sessionStorage.removeItem(authKey);}
async function authFetch(path,body){const res=await fetch(cfg.supabaseUrl+'/auth/v1/'+path,{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.publishableKey},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(data.msg||data.error_description||'Sign-in failed.');return data;}
async function api(body,{publicRequest=false}={}){
 if(demo)throw Error('This is a practice preview. No classroom decisions are sent.');
 if(!cfg.api)throw Error('Live classroom access is not configured yet.');
 if(auth?.kind==='teacher'&&!cfg.preview&&auth.expires<Date.now()+30000){const renewed=await authFetch('token?grant_type=refresh_token',{refresh_token:auth.refresh});auth={kind:'teacher',token:renewed.access_token,refresh:renewed.refresh_token,expires:Date.now()+renewed.expires_in*1000};remember();}
 const headers={'Content-Type':'application/json'};if(!publicRequest&&auth)headers[auth.kind==='student'?'x-student-token':'Authorization']=auth.kind==='student'?auth.token:'Bearer '+auth.token;
 const response=await fetch(cfg.api,{method:'POST',headers,body:JSON.stringify({classId,country:teacherCountry,role:teacherRole,...body}),signal:AbortSignal.timeout(15000)});
 const data=await response.json();if(!response.ok){const error=Error(data.error||'Could not save.');error.status=response.status;throw error;}return data;
}
function connection(ok){if(demo){online=false;$('connection').textContent='Practice preview · not a live class';document.querySelectorAll('#classroom button[data-write],#classroom form input,#classroom form select,#classroom form button:not(.planning-find)').forEach(b=>b.disabled=true);return;}online=ok;$('connection').textContent=ok?'Connected · changes sync automatically':'Reconnecting · decisions paused';document.querySelectorAll('#classroom button[data-write]').forEach(b=>b.disabled=!ok||busy||!!outbox.read()||b.dataset.movementLocked==='true');}
function setView(view,force=false){if(v&&view.revision<v.revision)return;if(view.teacher&&(view.assignment.country!==teacherCountry||view.assignment.role!==teacherRole))return;if(view.cells)cells=view.cells;if(v&&dirty&&!force&&v.phase===view.phase&&v.year===view.year&&v.revision!==view.revision){latest=view;notice('The class has new changes. Your unsaved entries are still here. Use “Review latest” before submitting.');if(!$('reviewLatest')){const b=document.createElement('button');b.id='reviewLatest';b.textContent='Review latest';b.onclick=()=>{dirty=false;setView(latest,true);latest=null;notice('Updated. Review your choices before saving.');};$('notice').append(' ',b);}return;}
 if(v&&dirty&&(v.phase!==view.phase||v.year!==view.year))notice('The teacher advanced the class. Unsaved entries from the previous phase were not submitted.');
 const changed=!v||v.revision!==view.revision||v.assignment.country!==view.assignment.country||v.assignment.role!==view.assignment.role||force;v=view;if(changed){dirty=false;render();}else if(v.teacher)renderRoster();connection(true);}
async function load(force=false){
 if(force)forceNext=true;if(polling||busy||!auth||!classId)return;
 polling=true;const requestedClass=classId,requestedAuth=auth,refresh=forceNext;forceNext=false;
 try{const data=await api({op:'state',revision:refresh?-1:v?.revision,includeMap:!cells.length});
 if(classId!==requestedClass||auth!==requestedAuth)return;
 if(data.view)setView(data.view,refresh);
 if(data.connections&&v?.teacher){for(const m of v.roster)m.connected=!!data.connections[m.id];renderRoster();}
 connection(true);
 }catch(e){if(classId!==requestedClass||auth!==requestedAuth)return;connection(false);if(e.status===401){auth=null;remember();entry();notice(e.message);}else notice(e.message);}
 finally{polling=false;if(forceNext&&auth&&classId&&!busy)load();}
}
async function recoverAction(){
 if(busy||!online||!v||!outbox.read())return;
 busy=true;connection(online);
 try{
  const result=await outbox.flush(context(),pending=>api({op:'command',classId:pending.classId,country:pending.country,role:pending.role,command:pending.command}));
  if(result.kind==='saved'){dirty=false;latest=null;setView(result.data.view,true);notice(result.data.duplicate?'Your earlier action was already saved.':'Saved.');}
  else if(result.kind==='pending'){connection(false);notice('Checking your earlier save. It may have arrived; wait for confirmation before making another decision.');}
  else if(result.kind==='signin'){connection(false);notice('Sign in again to confirm your earlier save.');}
  else if(result.kind==='reassigned'){forceNext=true;notice('Your assignment changed. Review your saved decisions with the teacher; the earlier action will not be retried.');}
  else if(result.kind==='rejected'){dirty=false;forceNext=true;notice('Review the latest class state before trying again. '+result.error.message);}
  else if(result.kind==='other')notice('Return to your earlier class and sign-in to confirm its pending save.');
 }catch(e){notice(e.message);}
 finally{busy=false;connection(online);if(forceNext)await load(true);}
}
async function action(type,args={}){
 if(demo){notice('Practice preview only. Your teacher’s class link and PIN unlock saved decisions.');return;}
 if(busy||!online)return;
 if(outbox.read()){notice('Wait for your earlier save to be confirmed.');await recoverAction();return;}
 if((type==='ready'&&args.ready||type==='advance')&&dirty){notice('Save your current form before marking ready or advancing.');return;}
 try{outbox.enqueue({...context(),command:{id:id(),revision:v.revision,type,args}});}catch(e){notice('Could not prepare a recoverable save: '+e.message);return;}
 await recoverAction();
}
function form(id,fn){const element=$(id);if(!element)return;element.addEventListener('input',()=>{dirty=true;});element.onsubmit=e=>{e.preventDefault();if(latest){notice('Review the latest class changes before saving this form.');return;}fn(element);};}
function btn(text,type,args={},className=''){return `<button type="button" data-write data-action="${type}" data-args="${esc(JSON.stringify(args))}" class="${className}">${esc(text)}</button>`;}
function wireActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,JSON.parse(b.dataset.args)));}
function country(n){return v.countries.find(c=>c.id===n)?.name||'Unclaimed';}
function entry(mode=studentPage?'student':'teacher'){PlanningView.reset();
 $('classroom').hidden=true;$('entry').hidden=false;$('logout').hidden=!auth;
 if(!cfg.api){studentEntry(false);return;}
 if(studentPage){studentEntry(true);return;}
 if(auth?.kind==='teacher'){teacherHome();return;}
 $('entry').innerHTML=`<section class="entry card"><p class="eyebrow">COUNCIL & CROWN</p><h1>${mode==='student'?'Your country needs you.':'Welcome, teacher.'}</h1><p>${mode==='student'?'Enter the PIN your teacher assigned. Your country, department and current task will load together.':'Sign in to manage your class and advance the year.'}</p><div class="tabs"><button id="studentTab">Student</button><button id="teacherTab">Teacher</button></div>${mode==='student'?`<form id="joinForm">${!classId?'<label>Class link<input name="link" type="url" required placeholder="Paste the link from your teacher"></label>':''}<label>Your six-digit PIN<input name="pin" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off" autofocus></label><button class="primary">Enter classroom</button></form>`:`<form id="teacherLogin">${cfg.preview?'<p class="warning">Local testing preview. Use the preview password supplied when starting the server.</p>':'<label>Teacher email<input name="email" type="email" autocomplete="username" required></label>'}${cfg.preview?'<label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in</button>':'<p>Use your approved teacher email. We’ll email a one-time sign-in link; students use their PINs.</p><button class="primary">Send sign-in link</button>'}</form>`}</section>`;
 $('studentTab').onclick=()=>entry('student');$('teacherTab').onclick=()=>entry('teacher');
 form('joinForm',async f=>{try{if(!classId){const link=new URL(string(f,'link'));classId=link.searchParams.get('class')||'';}const data=await api({op:'join',pin:string(f,'pin')},{publicRequest:true});auth={kind:'student',token:data.token};remember();history.replaceState({},'', '?class='+classId);setView(data.view,true);notice('You are signed in. Start with your checklist.');}catch(e){notice(e.message);}});
 form('teacherLogin',async f=>{const submit=f.querySelector('button');submit.disabled=true;try{if(cfg.preview){auth={kind:'teacher',token:string(f,'password')};await api({op:'list'});remember();if(classId)await load(true);else await teacherHome();}else{await authFetch('otp',{email:string(f,'email').trim(),create_user:true});notice('Check your email and open the sign-in link. It returns you to your teacher dashboard.');}}catch(e){auth=null;remember();notice(e.message);}finally{submit.disabled=false;}});

}
async function teacherHome(){try{const data=await api({op:'list'});$('classroom').hidden=true;$('entry').hidden=false;$('logout').hidden=false;$('entry').innerHTML=`<section class="entry card"><p class="eyebrow">TEACHER DASHBOARD</p><h1>Your classrooms</h1><div>${data.classes.map(c=>`<p><button data-class="${c.id}">${esc(c.name)} · Year ${c.year}${c.closed?' · closed':''}</button></p>`).join('')||'<p>Create your first shared class.</p>'}</div><hr><h2>Create a class</h2><form id="createClass"><label>Class name<input name="name" maxlength="80" required placeholder="Period 3"></label><label>Starting game<select name="source"><option value="new">New world</option><option value="local">Use this browser’s saved local game</option><option value="file">Upload a saved game</option></select></label><label>Saved game file (if uploading)<input name="file" type="file" accept=".json"></label><p class="muted">The original local save remains available. The shared class saves independently.</p><button class="primary">Create shared class</button></form></section>`;
 $('entry').querySelectorAll('[data-class]').forEach(b=>b.onclick=async()=>{classId=b.dataset.class;v=null;cells=[];teacherCountry=0;teacherRole='economy';history.replaceState({},'','?class='+classId);await load(true);});
 form('createClass',async f=>{const submit=f.querySelector('button');submit.disabled=true;try{let game;const source=string(f,'source');if(source==='local'){const raw=localStorage.getItem('council-regiments-v0.10');if(!raw)throw Error('No local game is saved in this browser. Upload a downloaded game instead.');game=JSON.parse(raw);}else if(source==='file'){const file=f.elements.file.files[0];if(!file)throw Error('Choose your saved game file.');if(file.size>35e6)throw Error('Choose a file under 35 MB.');game=JSON.parse(await file.text());}else game=RegimentGame.create(generateStudentWorld(crypto.getRandomValues(new Uint32Array(1))[0],GRIA_TEMPLATE));const data=await api({op:'create',name:string(f,'name'),game});classId=data.classId;cells=[];history.replaceState({},'','?class='+classId);setView(data.view,true);notice('Class created. Assign students below and share the class link.');}catch(e){notice(e.message);submit.disabled=false;}});
 }catch(e){notice(e.message);}}
function render(){
 PlanningView.reset();
 $('entry').hidden=true;$('classroom').hidden=false;$('logout').hidden=false;
 $('identity').textContent=`${v.name} · ${country(v.assignment.country)} · ${roles[v.assignment.role]}`;
 $('logout').hidden=demo;
 $('title').textContent=`Year ${v.year} · ${v.phaseTitle}`;$('subtitle').textContent=v.phaseHelp;
 const phaseIndex=['orders','movement','decisions','retreat','results'].indexOf(v.phase);$('steps').innerHTML=phaseNames.map((p,i)=>`<div class="${i===phaseIndex?'current':''}" ${i===phaseIndex?'aria-current="step"':''}><span class="step-number">${i+1}${i===2?' · WHEN NEEDED':''}</span>${p}</div>`).join('');
 $('tasks').innerHTML=v.tasks.map(t=>`<li>${esc(t)}</li>`).join('');
 $('readyArea').innerHTML=v.closed?'<p class="warning">Class closed.</p>':!v.required?'<p class="good">No required actions for you right now. Watch for the next step.</p>':`<p>${v.ready?'Your work is marked ready. Changing a decision makes your country’s team review it again.':'Finish your checklist, then let your teacher know you are ready.'}</p>${btn(v.ready?'Go back to working':'I’m ready','ready',{ready:!v.ready},'primary')}`;wireActions($('readyArea'));
 if(!v.teacher)$('readyArea').insertAdjacentHTML('beforeend','<p class="muted">Your teacher starts the next step. This screen updates automatically.</p>');
 $('balances').innerHTML=`<p class="eyebrow">${v.assignment.role==='economy'?'TREASURY AVAILABLE':roles[v.assignment.role].toUpperCase()+' AVAILABLE'}</p>${amounts(v.assignment.role==='economy'?v.country.stock:v.country.accounts[v.assignment.role])}<p class="muted">${v.phase==='results'?'These balances carry into next year.':'Spend only delivered resources. New allocations arrive at year-end.'}</p>`;
 $('goals').innerHTML='<p class="eyebrow">DEPARTMENT OBJECTIVES</p>'+(v.objectives.filter(o=>o.department===v.assignment.role).map(o=>`<div><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><progress max="1" value="${o.progress}"></progress><small>${esc(o.detail)}${o.done?' · Achieved':''}</small></div>`).join('')||'<p>Objectives will appear when this class uses the objectives release.</p>');
 $('teacherPanel').hidden=!v.teacher;$('teacherView').innerHTML='';if(v.teacher)renderTeacher();
 renderActions();renderSummary();renderMap();PlanningView.student({v,mapView,action});if(v.phase==='orders'&&v.assignment.role==='military')for(const u of v.units.filter(u=>u.country===v.country.id))MovementView.editor({host:$('unit-'+u.id),s:v,u,range:u.movement,disabled:demo||v.ready||u.readyTurn>v.year||u.supportTurn===v.year,save:(territory,intent,path)=>action('order',{unit:u.id,territory,intent,path})});MovementView.panel({host:$('actions'),s:v,country:v.country.id,disabled:demo,choose:v.assignment.role==='military'?decision=>action('encounter',{decision}):null,focus:id=>mapView.focus(id)});PlanningView.simulation({phase:v.phase,map:$('map').closest('.card'),controls:$('actions')});connection(online);
}
function renderTeacher(){
 $('teacherView').innerHTML=`<label>Preview country<select id="teacherCountry">${opts(v.countries.map(c=>[c.id,c.name]),v.assignment.country)}</select></label><label>Department<select id="teacherRole">${opts(Object.entries(roles),v.assignment.role)}</select></label>`;
 for(const element of [$('teacherCountry'),$('teacherRole')])element.onchange=async()=>{teacherCountry=Number($('teacherCountry').value);teacherRole=$('teacherRole').value;dirty=false;await load(true);};
 const link=new URL('student.html',location.href);link.searchParams.set('class',classId);
 $('teacherPanel').innerHTML=`<div class="section-title"><div><p class="eyebrow">TEACHER CONTROLS</p><h2>Bring the whole class forward.</h2></div><button id="classList">My classes</button></div><p>Class link: <a id="classLink" href="${esc(link.href)}">${esc(link.href)}</a></p><div class="row"><button id="copyLink">Copy class link</button><button id="exportGame">Download game backup</button>${btn(v.closed?'Reopen class':'Close class','close',{closed:!v.closed})}</div><div id="roster"></div><details><summary>Assign a student</summary><form id="assignForm"><input name="memberId" type="hidden"><div class="grid"><label>Student label<input name="label" maxlength="60" required placeholder="Student 1 or a nickname"></label><label>Country<select name="country">${opts(v.countries.map(c=>[c.id,c.name]),v.assignment.country)}</select></label><label>Department<select name="role">${opts(Object.entries(roles),'economy')}</select></label></div><button data-write class="primary">Generate student PIN</button></form></details><div id="pinResult" aria-live="polite"></div><hr><div id="blockers">${v.blockers.length?'<strong>Still needed:</strong><ul>'+v.blockers.map(b=>'<li>'+esc(b.text)+'</li>').join('')+'</ul>':'<p>All required decisions and readiness checks are complete.</p>'}</div><label class="checklabel"><input id="override" type="checkbox">Advance past “not ready” students (required game decisions still apply)</label><button id="advanceClass" data-write class="primary">${({orders:'Finish plans & start movement',movement:'Next movement',decisions:'Resolve responses & battles',retreat:'Finish final actions & calculate supplies',results:'Start year '+(v.year+1)})[v.phase]}</button>`;
 renderRoster();wireActions($('teacherPanel'));$('classList').onclick=()=>{classId='';v=null;cells=[];teacherCountry=0;teacherRole='economy';history.replaceState({},'','classroom.html');teacherHome();};$('copyLink').onclick=()=>navigator.clipboard.writeText(link.href).then(()=>notice('Class link copied.')).catch(()=>notice('Select and copy the class link above.'));
 $('exportGame').onclick=async()=>{try{const data=await api({op:'export'}),url=URL.createObjectURL(new Blob([JSON.stringify(data.game)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='council-year-'+v.year+'.json';a.click();URL.revokeObjectURL(url);}catch(e){notice(e.message);}};
 $('advanceClass').onclick=()=>action('advance',{overrideReadiness:$('override').checked});
 form('assignForm',f=>assign({memberId:string(f,'memberId')||undefined,label:string(f,'label'),assignedCountry:num(f,'country'),assignedRole:string(f,'role')}));
}
function renderRoster(){if(!$('roster'))return;$('roster').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Country / department</th><th>Connection</th><th>Progress</th><th>PIN / access</th></tr></thead><tbody>${v.roster.map(m=>`<tr><td>${esc(m.label)}</td><td>${esc(country(m.country))}<br>${roles[m.role]}</td><td>${m.disabled?'Disabled':m.connected?'Connected':'Disconnected'}</td><td>${m.disabled?'—':!m.required?'Waiting':m.ready?'Ready':'Working'}</td><td><button data-edit="${m.id}">Change assignment</button> <button data-reset="${m.id}">${m.disabled?'Enable & issue PIN':'Reset PIN'}</button>${m.disabled?'':` <button data-disable="${m.id}">Disable</button>`}</td></tr>`).join('')}</tbody></table></div><p class="muted">Changing a PIN signs that student out on every device. Students in the same country and department share its decisions.</p>`;
 $('roster').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const m=v.roster.find(m=>m.id===b.dataset.edit),f=$('assignForm');f.closest('details').open=true;for(const [k,value] of Object.entries({memberId:m.id,label:m.label,country:m.country,role:m.role}))f.elements[k].value=value;f.querySelector('button').textContent='Save assignment & issue new PIN';f.elements.label.focus();});for(const kind of ['reset','disable'])$('roster').querySelectorAll('[data-'+kind+']').forEach(b=>b.onclick=()=>{const m=v.roster.find(m=>m.id===b.dataset[kind]);assign({memberId:m.id,label:m.label,assignedCountry:m.country,assignedRole:m.role,disabled:kind==='disable'});});}
async function assign(data){if(busy)return;if(outbox.read()){notice('Wait for your earlier save to be confirmed.');return;}busy=true;try{const out=await api({op:'assign',revision:v.revision,requestId:id(),...data});setView(out.view,true);$('pinResult').innerHTML=out.pin?`<div class="good"><strong>${esc(data.label)} · ${esc(country(data.assignedCountry))} · ${roles[data.assignedRole]}</strong><div class="pin">${out.pin}</div><p>Give this PIN privately to the student. It is shown once; reset it if lost.</p></div>`:'<p>Student access updated.</p>';notice('Assignment saved.');}catch(e){notice(e.message);}finally{busy=false;connection(online);}}
function fields(prefix,stock){return goods.map(g=>`<label>${g}<input name="${prefix}-${g}" type="number" min="0" step="1" required value="${stock?.[g]??0}"></label>`).join('');}
function bundle(f,prefix){return Object.fromEntries(goods.map(g=>[g,num(f,prefix+'-'+g)]));}
function renderActions(){const host=$('actions'),c=v.country,role=v.assignment.role,own=v.territories.filter(t=>t.owner===c.id);if(v.phase==='movement'){host.replaceChildren();return;}host.innerHTML='<h2>'+({orders:'Make your plan',movement:'Movement simulation',decisions:'Your responses',retreat:'Finish this year’s decisions',results:'Review before the next year'})[v.phase]+'</h2>';
 if(v.phase==='results'){host.innerHTML+='<p>Read the year-end summary below, then mark yourself ready. Your teacher starts the next year for everyone.</p>';return;}
 if(role==='economy'&&v.phase==='orders'){
 host.innerHTML+=`<p>Reserve civilian food in Treasury: <strong>${own.reduce((n,t)=>n+t.foodNeed,0)} needed</strong>. Armies eat from Military after deliveries.</p><form id="allocations"><div class="grid">${['military','research'].map(d=>`<fieldset><legend>${roles[d]} delivery at year-end</legend>${fields(d,c.allocations[d])}</fieldset>`).join('')}</div><p class="muted">These are total pending allocations, not extra payments. Unassigned resources stay in Treasury.</p><button data-write class="primary">Save department funding</button></form>`;
 form('allocations',f=>action('allocate',{plan:{military:bundle(f,'military'),research:bundle(f,'research')}}));renderExchanges(host,'trade');
 host.insertAdjacentHTML('beforeend',`<h3>Settlement improvements</h3><p>Select an owned territory on the map below to build or repair.</p>`);
 }else if(role==='economy'&&v.phase==='retreat'){
 host.innerHTML+=`<p>Use current Treasury food. New production arrives after this decision.</p><form id="foodPlan">${own.map(t=>`<label>${esc(t.name)} · needs ${t.foodNeed} · happiness ${t.happiness}<input name="food-${t.id}" type="number" min="0" max="${t.foodNeed}" step="1" required value="${c.foodPlan[t.id]??''}"></label>`).join('')}<button type="button" id="fullFood">Fill full meals</button> <button data-write class="primary">Save & confirm food plan</button></form><p>${c.foodConfirmed?'Food plan confirmed.':'Enter every amount, including zero if food is unavailable.'}</p>`;
 $('fullFood').onclick=()=>{for(const t of own)$('foodPlan').elements['food-'+t.id].value=t.foodNeed;dirty=true;};form('foodPlan',f=>action('feed',{plan:Object.fromEntries(own.map(t=>[t.id,num(f,'food-'+t.id)]))}));
 }else if(role==='military'){
 const units=v.units.filter(u=>u.country===c.id);
 if(v.phase==='orders'){
 host.innerHTML+=`<p><a href="#mapTools">Jump to the movement map ↓</a></p><form id="recruit"><h3>Recruit a regiment</h3><label>Type<select name="kind">${opts(Object.keys(RegimentGame.types).map(k=>[k,RegimentGame.types[k].name+' · '+amount(v.recruitCosts[k].cost)+(v.recruitCosts[k].unlocked?'':' · research required')]),'spears')}</select></label><label>Settlement<select name="territory">${opts([...new Set(v.recruitSites)].map(n=>[n,v.territories[n].name]),'')}</select></label><p>Pay from your delivered Military account. Recruits train until next year.</p><button data-write>Recruit</button></form><h3>Your regiments</h3><p>Pair cavalry and artillery in the same territory to move together at their average speed, rounded down. Either order moves both. Detach during planning to restore separate movement; both orders are cleared.</p>`;
 form('recruit',f=>action('recruit',{kind:string(f,'kind'),territory:num(f,'territory')}));
 for(const u of units){host.insertAdjacentHTML('beforeend',`<form class="subcard" id="unit-${u.id}"><h3>${RegimentGame.types[u.type].name} #${u.id} · ${u.hp} health</h3><p>Movement: ${u.movement} territories${u.pairedWith?` · Paired with #${u.pairedWith}`:""}</p>${u.pairedWith?btn("Detach partner","detach",{unit:u.id}):(u.pairOptions||[]).map(id=>btn("Pair with #"+id,"attach",{unit:u.id,other:id})).join(" ")}<p>At ${esc(v.territories[u.territory].name)} · ${u.readyTurn>v.year?'Training until next year':'Ready'} · Equipment tier ${u.gear}</p><label>Destination<select name="territory">${opts(v.territories.filter(t=>Object.hasOwn(u.legalRoutes||{},t.id)||t.id===u.territory).map(t=>[t.id,t.name+' · '+country(t.owner)]),u.order?.destination??u.territory)}</select></label><label>Order<select name="intent">${opts([['move','Move / hold'],['capture','Move & capture']],u.order?.intent??'move')}</select></label><button data-write>Save order</button> ${btn('Clear order','clearOrder',{unit:u.id})} ${goods.some(g=>u.equipCost[g]>0)?btn('Re-equip · '+amount(u.equipCost),'equip',{unit:u.id}):'<span class="tag">Best known equipment</span>'}<p class="muted">${u.order?'Saved: '+esc(u.order.intent)+' → '+esc(v.territories[u.order.destination].name):'No order saved: this regiment will hold.'}</p></form>`);form('unit-'+u.id,f=>action('order',{unit:u.id,territory:num(f,'territory'),intent:string(f,'intent')}));}
 }
 if(v.phase==='decisions')for(const x of v.conflicts){host.insertAdjacentHTML('beforeend',`<form class="subcard" id="target-${x.territory}"><h3>Meeting at ${esc(v.territories[x.territory].name)}</h3><label>Your response<select name="target">${opts([['','Choose…'],['hold','Hold — do not attack'],...x.countries.filter(n=>n!==c.id).map(n=>[n,'Attack '+country(n)])],Object.hasOwn(v.choices,x.territory+':'+c.id)?v.choices[x.territory+':'+c.id]??'hold':'')}</select></label><button data-write>Save target</button></form>`);form('target-'+x.territory,f=>{const target=string(f,'target');if(!target){notice('Choose a response.');return;}action('target',{territory:x.territory,target:target==='hold'?null:Number(target)});});}
 if(['orders','decisions'].includes(v.phase)){
 host.insertAdjacentHTML('beforeend',`<details><summary>Alliances</summary><form id="alliance"><label>Country<select name="country">${opts(v.countries.filter(k=>k.id!==c.id).map(k=>[k.id,k.name]),'')}</select></label><button data-write>Offer alliance</button></form>${v.allianceOffers.filter(o=>o.to===c.id).map(o=>'<p>'+esc(country(o.from))+' offered an alliance. '+btn('Accept alliance','allianceAccept',{country:o.from})+'</p>').join('')}<p>Current allies: ${esc(v.alliances.filter(a=>a.split('-').map(Number).includes(c.id)).map(a=>country(a.split('-').map(Number).find(n=>n!==c.id))).join(', ')||'None')}</p></details>`);form('alliance',f=>action('allianceOffer',{country:num(f,'country')}));
 }
 if(v.phase==='retreat'){
 for(const u of units.filter(u=>u.retreat?.required)){host.insertAdjacentHTML('beforeend',`<form class="subcard" id="retreat-${u.id}"><h3>Regiment #${u.id} · ${u.hp} health</h3>${u.retreatOptions.length?`<label>Safe retreat<select name="territory">${opts([['','Choose a safe neighbor'],...u.retreatOptions.map(n=>[n,v.territories[n].name])],u.retreatTo??'')}</select></label><button data-write>Save retreat</button>`:'<p>No safe neighboring territory. This regiment surrenders when the teacher finishes final actions.</p>'}</form>`);form('retreat-'+u.id,f=>{if(string(f,'territory')===''){notice('Choose a safe territory.');return;}action('retreat',{unit:u.id,territory:num(f,'territory')});});}
 for(const p of v.captures){host.insertAdjacentHTML('beforeend',`<form class="subcard" id="capture-${p.territory}"><h3>Shared capture: ${esc(v.territories[p.territory].name)}</h3><p>Every participating country must choose the same recipient. Disagreement destroys the settlement and forces withdrawal.</p><label>Recipient<select name="recipient">${opts([['','Choose…'],[-1,'No agreement — destroy and withdraw'],...p.claimants.map(n=>[n,country(n)])],p.votes[c.id]??'')}</select></label><button data-write>Submit ownership decision</button></form>`);form('capture-'+p.territory,f=>{if(string(f,'recipient')===''){notice('Choose an ownership decision.');return;}action('capture',{territory:p.territory,recipient:num(f,'recipient')});});}
 if(!units.some(u=>u.retreat?.required)&&!v.captures.length)host.innerHTML+='<p>No required retreats or shared captures for your country.</p>';
 }
 }else if(role==='research'&&v.phase==='orders'){
 host.innerHTML+=`<p>Current project: <strong>${c.project?esc(D.techs[c.project].name):'None'}</strong>${c.project?' · '+(c.researchProgress[c.project]||0)+' / '+D.techs[c.project].rounds+' progress':''}</p><form id="research"><label>Discovery<select name="tech">${opts(Object.keys(D.techs).filter(k=>D.canLearn(c,k)).map(k=>[k,D.techs[k].name+' · '+amount(D.researchCost(c,k))+' per funded year']),c.project)}</select></label><button data-write>Choose project</button></form><p>Next installment: ${amount(v.researchCost)}. Arrange joint research before either partner funds it.</p>${c.funding?'<p class="good">This year’s research installment is funded.</p>':btn('Fund this year’s installment','fund',{},'primary')}<p>Select an owned settlement on the map to manage its facilities.</p>`;
 form('research',f=>action('research',{tech:string(f,'tech')}));renderExchanges(host,'research');
 for(const [index,k] of (c.capturedKnowledge||[]).entries()){host.insertAdjacentHTML('beforeend',`<form class="subcard" id="knowledge-${index}"><h3>Captured archives · ${esc(v.territories[k.territory].name)}</h3><label>Discovery<select name="tech">${opts(k.options.filter(t=>D.canLearn(c,t)).map(t=>[t,D.techs[t].name]),'')}</select></label><button data-write>Study discovery</button></form>`);form('knowledge-'+index,f=>action('claimKnowledge',{index,tech:string(f,'tech')}));}
 }else host.innerHTML+='<p>Your department has no required decisions in this phase. Review the map and help your country discuss its next steps.</p>';
 if(v.battles.length&&v.phase==='retreat')host.insertAdjacentHTML('beforeend',battleCards(v.battles));wireActions(host);
}
function renderExchanges(host,kind){const c=v.country;for(const d of v.disruptions||[])host.insertAdjacentHTML('beforeend','<p class="warning">Relations with '+esc(country(d.country))+' are disrupted by an attack. Trade, knowledge sharing and joint research can resume in year '+d.resumeYear+' after a quiet year.</p>');host.insertAdjacentHTML('beforeend',`<details><summary>${kind==='trade'?'Trade resources':'Share knowledge & cooperate'}</summary><form id="exchange"><label>Partner<select name="country">${opts(v.countries.filter(k=>k.id!==c.id).map(k=>[k.id,k.name]),'')}</select></label>${kind==='trade'?`<div class="grid"><fieldset><legend>We give (reserved now)</legend>${fields('give',{})}</fieldset><fieldset><legend>We request</legend>${fields('want',{})}</fieldset></div>`:`<label>Offer type<select name="kind"><option value="knowledge">Share a discovery for free</option><option value="cooperate">Joint research — same project required</option></select></label><label>Discovery to share<select name="tech">${opts(c.knowledge.map(k=>[k,D.techs[k].name]),'')}</select></label>`}<button data-write>Send offer</button></form><div>${v.exchanges.map(o=>`<article class="subcard"><strong>${esc(country(o.from))} → ${esc(country(o.to))}</strong><p>${o.kind==='trade'?'Gives '+amount(o.data.give)+'; requests '+amount(o.data.want):esc(D.techs[o.data.tech]?.name)} · ${esc(o.status)}</p>${o.status==='pending'?(o.to===c.id?btn('Accept','exchangeAccept',{offer:o.id}):'')+btn(o.from===c.id?'Cancel':'Decline','exchangeCancel',{offer:o.id}):''}</article>`).join('')||'<p>No offers yet.</p>'}</div></details>`);
 form('exchange',f=>action('exchangeOffer',{country:num(f,'country'),kind:kind==='trade'?'trade':string(f,'kind'),data:kind==='trade'?{give:bundle(f,'give'),want:bundle(f,'want')}:{tech:string(f,'tech')}}));}
function battleCards(battles){return '<h3>Battle results</h3>'+battles.map(b=>`<div class="subcard"><h3>${esc(v.territories[b.territory].name)}</h3>${b.records.map(u=>`<p>${esc(country(u.country))} · ${RegimentGame.types[u.type].name} #${u.id}: ${u.before} entered, ${u.lost} lost, <strong>${u.remaining} remain</strong>.</p>`).join('')}</div>`).join('');}
function renderSummary(){const host=$('summary'),s=v.summary;host.hidden=!s;if(!s)return;host.innerHTML=`<p class="eyebrow">${s.year===v.year?'YEAR-END':'LAST YEAR'} REPORT</p><h2>Year ${s.year} · What changed for ${esc(v.country.name)}</h2><div class="grid"><div><h3>Produced</h3>${amounts(s.produced)}</div><div><h3>Food used</h3><p><strong>${s.civilianFood}</strong> civilian food from Treasury.</p><p><strong>${s.militaryFood.paid} / ${s.militaryFood.need}</strong> military meals supplied after deliveries.</p></div></div><h3>Department deliveries</h3><p>Military: ${amount(s.deliveries.military)}</p><p>R&D: ${amount(s.deliveries.research)}</p><h3>Available for year ${s.year+1}</h3><div class="table-wrap"><table><thead><tr><th>Account</th>${goods.map(g=>'<th>'+g+'</th>').join('')}</tr></thead><tbody>${Object.entries(s.availableNextYear).map(([name,stock])=>'<tr><td>'+esc(name==='treasury'?'Treasury':roles[name])+'</td>'+goods.map(g=>'<td>'+stock[g]+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p class="muted">Final balances include meals, deliveries, refunds and city effects. Starting the next year does not award these supplies a second time.</p><p><strong>New discoveries:</strong> ${esc(s.discoveries.map(x=>x.name).join(', ')||'None this year')}</p><p><strong>Gained:</strong> ${esc(s.territoriesGained.join(', ')||'No territory')}<br><strong>Lost:</strong> ${esc(s.territoriesLost.join(', ')||'No territory')}</p><details><summary>Read the year’s events</summary>${s.events.map(e=>'<p>'+esc(e)+'</p>').join('')}${battleCards(s.battles)}</details>`;}
const mapView=ClassroomMap.attach({canvas:$('map'),layer:$('mapLayer'),intent:$('mapIntent'),status:$('mapStatus'),tools:$('mapTools'),legend:$('mapLegend'),select:n=>{selected=n;$('mapTerritory').value=n??'';renderTerritory();},commit:(unit,territory,intent)=>{if(dirty||latest){notice('Save your current form and review the latest changes before dragging a regiment.');return;}action('order',{unit,territory,intent});},canWrite:()=>online&&!busy&&!outbox.read()&&!demo&&!v?.closed});
function renderMap(){mapView.update(v,cells,selected,demo);$('mapTerritory').innerHTML=opts([['','Choose a territory'],...v.territories.map(t=>[t.id,(t.id+1)+' · '+t.name+' · '+country(t.owner)])],selected??'');$('mapTerritory').onchange=()=>{selected=$('mapTerritory').value===''?null:Number($('mapTerritory').value);mapView.select(selected);renderTerritory();};renderTerritory();}
function renderTerritory(){const host=$('territoryDetail'),t=v.territories[selected];if(!t){host.innerHTML='<p>Select a territory to see its supplies and available actions.</p>';return;}host.innerHTML=`<h3>${esc(t.name)} · ${esc(country(t.owner))}</h3><p>${RegimentGame.settlementLevels[t.settlementLevel]} · Happiness ${t.happiness}/100 · Civilian need ${t.foodNeed} food</p><p>Expected production: ${amount(t.output)} · Defenses ${t.defenseHp}/${t.maxDefense}</p>`;if(t.owner!==v.country.id||v.phase!=='orders')return;if(v.assignment.role==='economy'){for(const kind of ['settlement','fortification']){const data=t.construction[kind];host.innerHTML+=btn('Upgrade '+kind+' · '+amount(data.cost),'build',{territory:t.id,kind})+(data.requires?'<p class="muted">Requires '+esc(D.techs[data.requires].name)+'</p>':'');}if(t.defenseHp<t.maxDefense)host.innerHTML+=btn('Repair defenses','repair',{territory:t.id});}
 if(v.assignment.role==='research'&&t.settlementLevel){host.innerHTML+=`<h3>City facilities · ${t.facilities.length}/${t.settlementLevel} slots</h3><form id="install"><label>Facility<select name="kind">${opts(Object.entries(D.facilities).filter(([k])=>!t.facilities.includes(k)).map(([k,f])=>[k,f.name+' · '+amount(f.cost)+' · requires '+D.techs[f.tech].name]),'')}</select></label><button data-write>Install facility</button></form>`;form('install',f=>action('install',{territory:t.id,kind:string(f,'kind')}));for(const k of t.facilities){const f=D.facilities[k];host.insertAdjacentHTML('beforeend',`<form id="facility-${k}" class="subcard"><h3>${f.name}</h3><p>${f.action}</p><p>Cost: ${amount(f.actionCost)}</p>${k==='hospital'?`<label>Regiment<select name="unit">${opts(v.units.filter(u=>u.country===v.country.id&&u.territory===t.id&&u.hp<100).map(u=>[u.id,'#'+u.id+' · '+u.hp+' health']),'')}</select></label>`:''}<button data-write>Use ${f.name}</button></form>`);form('facility-'+k,f=>action('cityAction',{territory:t.id,kind:k,unit:k==='hospital'?num(f,'unit'):null}));}}
 wireActions(host);connection(online);
}

function studentEntry(configured){
 $('entry').innerHTML=`<section class="student-entry"><div class="welcome-copy"><p class="eyebrow">YOUR CLASSROOM ADVENTURE</p><h1>One country.<br>Make your part count.</h1><p class="lead">Plan with your team, make decisions, and discover what changes each year.</p><ol class="join-steps"><li><strong>Join your class</strong><span>Use your teacher’s link and six-digit PIN.</span></li><li><strong>Follow your next steps</strong><span>Your country and department are already assigned.</span></li><li><strong>Save. Mark ready. Stay together.</strong><span>Your screen follows the teacher into the next phase.</span></li></ol></div><section class="card join-card"><p class="eyebrow">STUDENT SIGN-IN</p><h2>Your country needs you.</h2><p>Keep your PIN to yourself. No email or student account is needed.</p>${configured?`<form id="joinForm">${!classId?'<label>Your teacher’s class link<input name="link" type="url" required placeholder="Paste your class link"></label>':'<p class="good">Class link loaded. Enter your PIN below.</p>'}<label for="studentPin">Your six-digit PIN</label><input id="studentPin" name="pin" class="pin-input" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off" placeholder="••••••" aria-describedby="pinHelp"><p id="pinHelp" class="muted">Lost your PIN? Ask your teacher for a new one.</p><button class="primary join-button">Enter my classroom</button></form>`:'<p class="setup-note">Live class sign-in is being connected. You can explore the student screens below while your teacher finishes setup.</p>'}<hr><a class="preview-link" href="student.html?preview=1">Explore the student screens →</a><p class="muted">Practice preview · no class decisions are saved.</p></section></section>`;
 form('joinForm',async f=>{const submit=f.querySelector('button');submit.disabled=true;try{if(f.elements.link){const link=new URL(string(f,'link'));const candidate=link.searchParams.get('class');if(link.origin!==location.origin||!candidate)throw Error('Paste the complete class link from your teacher.');classId=candidate;}const data=await api({op:'join',pin:string(f,'pin')},{publicRequest:true});auth={kind:'student',token:data.token};remember();history.replaceState({},'', '?class='+encodeURIComponent(classId));setView(data.view,true);notice('Welcome. Check your country and department, then follow your next steps.');}catch(e){notice(e.message);submit.disabled=false;}});
}
async function showDemo(){
 try{const response=await fetch('classroom-demo.json');if(!response.ok)throw Error('The preview could not load. Please refresh.');demoData=await response.json();cells=demoData.cells;
 $('demoBar').hidden=false;$('demoBar').innerHTML=`<div><strong>Practice preview</strong><p>Sample country and supplies. Controls are read-only; nothing is sent to a class.</p></div><label>Department<select id="previewRole">${opts(Object.entries(roles),demoRole)}</select></label><label>See a phase<select id="previewPhase">${opts(['orders','movement','decisions','retreat','results'].map((p,i)=>[p,({orders:'Start & plan',movement:'Movement',decisions:'Respond',retreat:'Results & final actions',results:'Year-end summary'})[p]]),demoPhase)}</select></label><a href="student.html">Back to sign-in</a>`;
 const display=()=>{demoRole=$('previewRole').value;demoPhase=$('previewPhase').value;v=structuredClone(demoData.views[demoRole][demoPhase]);selected=v.country.capital??null;render();};$('previewRole').onchange=display;$('previewPhase').onchange=display;display();
 }catch(e){notice(e.message);studentEntry(false);}
}

$('logout').onclick=async()=>{if(busy){notice('Wait for the current save to finish before signing out.');return;}try{if(auth?.kind==='student')await api({op:'logout'});}catch{}auth=null;remember();v=null;cells=[];online=false;entry();notice('Signed out.');};
window.addEventListener('online',()=>load(true));window.addEventListener('offline',()=>connection(false));
setInterval(async()=>{if(auth&&classId&&!document.hidden){await load();await recoverAction();}},2500);
async function start(){
 const callback=ClassroomAuth.parse(location.hash);
 if(callback){
  history.replaceState({},'',location.pathname+location.search);
  if(studentPage||demo||cfg.preview){entry();notice('Open your sign-in link on the teacher page.');return;}
  if(callback.error){entry();notice(callback.error);return;}
  auth=callback.auth;
  try{await api({op:'list'});remember();if(classId)await load(true);else await teacherHome();notice('Signed in as teacher.');}
  catch(e){auth=null;remember();entry();notice(e.message);}
  return;
 }
 if(demo)showDemo();else if(auth&&classId)load(true);else entry();
}
start();
})();
